#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_update_non_head_node_nonzero_ct_zero_wt_nonzero_tat(void) {
    // Setup: Build a linked list with at least two nodes.
    // Path conditions:
    // 1. The target node is NOT the head (ptr != NULL && ptr->ID != id) -> loop executes and exits.
    // 2. ct != 0 -> update CT.
    // 3. wt == 0 -> skip WT update.
    // 4. tat != 0 -> update TAT.
    int ids[] = {1, 2, 3};
    int ats[] = {0, 1, 2};
    int bts[] = {5, 4, 3};
    int priorities[] = {1, 2, 3};
    int size = 3;
    node *root = helper_build_process_queue(ids, ats, bts, priorities, size);
    TEST_ASSERT_NOT_NULL(root);

    // Verify initial state of node with ID 2 (non-head node).
    node *ptr = root;
    while (ptr != NULL && ptr->ID != 2) {
        ptr = ptr->next;
    }
    TEST_ASSERT_NOT_NULL(ptr);
    TEST_ASSERT_EQUAL_INT(0, ptr->CT);
    TEST_ASSERT_EQUAL_INT(0, ptr->WT);
    TEST_ASSERT_EQUAL_INT(0, ptr->TAT);

    // Test: Update node with ID 2, ct=100 (non-zero), wt=0 (zero), tat=200 (non-zero).
    update(&root, 2, 100, 0, 200);

    // Assertions: Verify only CT and TAT were updated, WT remains zero.
    ptr = root;
    while (ptr != NULL && ptr->ID != 2) {
        ptr = ptr->next;
    }
    TEST_ASSERT_NOT_NULL(ptr);
    TEST_ASSERT_EQUAL_INT(100, ptr->CT);
    TEST_ASSERT_EQUAL_INT(0, ptr->WT);
    TEST_ASSERT_EQUAL_INT(200, ptr->TAT);

    // Verify other nodes unchanged.
    ptr = root;
    TEST_ASSERT_EQUAL_INT(1, ptr->ID);
    TEST_ASSERT_EQUAL_INT(0, ptr->CT);
    TEST_ASSERT_EQUAL_INT(0, ptr->WT);
    TEST_ASSERT_EQUAL_INT(0, ptr->TAT);
    ptr = ptr->next->next; // Node ID 3
    TEST_ASSERT_EQUAL_INT(3, ptr->ID);
    TEST_ASSERT_EQUAL_INT(0, ptr->CT);
    TEST_ASSERT_EQUAL_INT(0, ptr->WT);
    TEST_ASSERT_EQUAL_INT(0, ptr->TAT);

    // Cleanup
    helper_cleanup_process_queue(&root);
    TEST_ASSERT_NULL(root);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_update_non_head_node_nonzero_ct_zero_wt_nonzero_tat);
    return UNITY_END();
}

